"""Original practice questions linking the supplied readings to Andriy's Weeks 1–4."""

def build_reading_questions():
    bank = []
    def mc(group, text):
        for i, line in enumerate(text.strip().splitlines(), 1):
            q, a, b, c, d, explanation, ref, topic, slide, level = line.split('|')
            bank.append(dict(id=f'{group}-rm{i:02}', group=group, type='mcq', prompt=q,
                options=[a,b,c,d], correct=0, explanation=explanation,
                source=f'{ref} · {slide}', readingRef=ref, lectureRef=slide,
                book='norman' if ref.startswith('Norman') else 'id', origin='reading',
                topic=topic, level='application' if level=='a' else 'concept'))
    def sa(group, text):
        for i, line in enumerate(text.strip().splitlines(), 1):
            q,a,b,keys,ref,topic,slide = line.split('|')
            bank.append(dict(id=f'{group}-rs{i:02}', group=group, type='short', prompt=q,
                answer=[a,b], keyPoints=keys.split('~'), source=f'{ref} · {slide}',
                readingRef=ref, lectureRef=slide, book='norman' if ref.startswith('Norman') else 'id',
                origin='reading', topic=topic, level='application'))

